package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyOperationExecutor.Result;
import org.jlinalg.study.StudyOperationExecutor.State;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.yaml.snakeyaml.Yaml;

class StudyBinaryRareVariantsTest {
    @TempDir Path root;
    private Map<String,Object> policy;
    private Map<String,Object> study;
    private Context scores;
    private Path masks;
    private static double[] vector(Map<?,?> c,String key){return ((List<?>)c.get(key)).stream().mapToDouble(v->((Number)v).doubleValue()).toArray();}
    private void setup(boolean split,long maximumWork)throws Exception{
        Map<?,?> reference=new Yaml().load(Files.readString(Path.of("src/test/resources/conditional-binary-set/reference.json")));Map<?,?> data=(Map<?,?>)((List<?>)reference.get("cases")).get(0);double[] y=vector(data,"y");var g=(List<?>)data.get("genotype");
        var binary=new LinkedHashMap<String,Object>(Map.of("mode","exact","strata_column","stratum","maximum_work",maximumWork));policy=new LinkedHashMap<>(Map.of("enabled",true,"trait_id","disease","weights","default","acat_mac_threshold",2,"masks",List.of(Map.of("id","coding","consequences",List.of("coding"),"maximum_maf",.5)),"binary",binary));
        Map<String,Object> dataset=Map.of("id","C1","cohort","A","type","gwas","stage","processed_matrix","genome_build","GRCh38","annotation_release","synthetic-1","files",Map.of("matrix","genotypes.vcf","phenotype","phenotype.tsv","variant_annotation","annotation.tsv"),"columns",Map.of("sample_id","id","phenotypes",Map.of("disease","disease")));
        var analysis=new LinkedHashMap<String,Object>(Map.of("association",Map.of("model","glm","family","binomial","link","logit"),"rare_variants",policy,"multiple_testing",Map.of("method","BY","alpha",.05)));
        study=new LinkedHashMap<>(Map.of("datasets",List.of(dataset),"hypotheses",List.of(Map.of("id","H","outcome","disease","covariates",List.of("stratum"),"inputs",Map.of("discovery",List.of("C1")),"analysis",analysis))));
        StringBuilder vcf=new StringBuilder("##fileformat=VCFv4.2\n##contig=<ID=1>\n##INFO=<ID=R2,Number=1,Type=Float,Description=\"Quality\">\n##FORMAT=<ID=GT,Number=1,Type=String,Description=\"Genotype\">\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT");for(int i=0;i<y.length;i++)vcf.append("\tprivate_s").append(i);vcf.append('\n');
        StringBuilder annotation=new StringBuilder("variant_id\tset_id\tconsequence\n");for(int j=0;j<4;j++){vcf.append("1\t").append(100+j).append("\trs").append(j).append("\tA\tG\t.\tPASS\tR2=1\tGT");for(int i=0;i<y.length;i++){double x=((Number)((List<?>)g.get(i)).get(j)).doubleValue();vcf.append(x==0?"\t0/0":x==1?"\t0/1":"\t1/1");}vcf.append('\n');annotation.append("1:").append(100+j).append(":A:G\t").append(split?(j==0?"G1":"G2"):"G1").append("\tcoding\n");}Files.writeString(root.resolve("genotypes.vcf"),vcf);Files.writeString(root.resolve("annotation.tsv"),annotation);
        StringBuilder pheno=new StringBuilder("id\tdisease\tstratum\n");for(int i=0;i<y.length;i++)pheno.append("private_s").append(i).append('\t').append((int)y[i]).append('\t').append(i<6?"a":"b").append('\n');Files.writeString(root.resolve("phenotype.tsv"),pheno);
        var qc=context("inputs/qc","participant_qc",Map.of());Files.copy(root.resolve("phenotype.tsv"),qc.outputDirectory().resolve("analysis-phenotype.tsv"));seal(qc,new Result(State.COMPLETE,"prefit input",List.of("analysis-phenotype.tsv"),Map.of("dataset","C1")));
        var mask=context("inputs/masks","rare_variant_masks",Map.of());var mr=new StudyCliExecutor().execute(mask);assertEquals(State.COMPLETE,mr.state(),mr.summary());seal(mask,mr);masks=mask.outputDirectory();
        scores=context("inputs/scores","rare_variant_scores",Map.of("qc",qc.outputDirectory(),"masks",masks));var sr=new StudyCliExecutor().execute(scores);assertEquals(State.COMPLETE,sr.state(),sr.summary());seal(scores,sr);
    }
    private Context context(String path,String type,Map<String,Path> dependencies)throws Exception{Path folder=root.resolve(path);Files.createDirectories(folder);return new Context(root,folder,Map.of("id",path.replace('/','-'),"type",type,"hypothesis","H","datasets",List.of("C1"),"dataset_id","C1"),study,Map.of(),dependencies);}
    private Context analysis(String run)throws Exception{return context("runs/"+run+"/operations/rare","rare_variant_analysis",Map.of("scores",scores.outputDirectory(),"masks",masks));}
    private static void seal(Context c,Result r)throws Exception{var hashes=new LinkedHashMap<String,Object>();try(var files=Files.walk(c.outputDirectory())){for(Path p:files.filter(Files::isRegularFile).toList())hashes.put(c.outputDirectory().relativize(p).toString().replace('\\','/'),FollowupSupport.hash(p));}StudyPublicEvidence.write(c.outputDirectory().resolve("manifest.yaml"),Map.of("operation_id",c.operation().get("id"),"operation_type",c.operation().get("type"),"hypothesis","H","datasets",List.of("C1"),"state",r.state().value(),"details",r.details(),"output_sha256",hashes));}
    @Test void privateBinaryExportRetainsMacOneAndNativeTestsHaveNoGaussianEffects()throws Exception{
        setup(false,1000000);var metadata=StudyYaml.loadArtifact(scores.outputDirectory().resolve("scores.yaml"));assertEquals(StudyBinaryRareScores.KIND,metadata.get("kind"));assertEquals(4,((Number)metadata.get("retained_variants_with_mac_below_20")).intValue());assertEquals(false,metadata.get("single_variant_mac_cutoff_applied"));assertEquals(5,DelimitedData.readResult(scores.outputDirectory().resolve("conditional-samples.tsv")).header().size());assertTrue(Files.readString(scores.outputDirectory().resolve("conditional-genotypes.tsv")).startsWith("variant_id\trow_0"));
        var c=analysis("one");var r=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,r.state(),r.summary());var t=DelimitedData.readResult(c.outputDirectory().resolve("rare-primary-results.tsv"));assertEquals(5,t.rows().size());for(String[] row:t.rows()){assertEquals("unsigned_set",row[t.column("result_type")]);assertEquals("NA",row[t.column("beta")]);assertEquals("NA",row[t.column("se")]);assertEquals("NA",row[t.column("direction")]);assertFalse(row[t.column("adjusted_p")].equals("NA"));assertTrue(Double.isFinite(Double.parseDouble(row[t.column("log_p_value")])));}assertEquals(true,r.details().get("rare_primary_complete"));assertFalse(String.valueOf(r.details()).contains("private_s"));
        try(var files=Files.list(c.outputDirectory().resolve("binary-fit-cache"))){assertEquals(1,files.count());}
    }
    @Test void aLargerWorkBudgetReusesACompleteGeneFromAnUnresolvedPriorFamily()throws Exception{
        setup(true,5000);var first=analysis("first");var r1=new StudyCliExecutor().execute(first);assertEquals(State.WAITING_FOR_INPUT,r1.state(),r1.summary());assertEquals(false,r1.details().get("rare_primary_complete"));var t1=DelimitedData.readResult(first.outputDirectory().resolve("rare-primary-results.tsv"));for(String[] row:t1.rows())assertEquals("NA",row[t1.column("adjusted_p")]);seal(first,r1);List<Path> files;try(var stream=Files.list(first.outputDirectory().resolve("binary-fit-cache"))){files=stream.toList();}assertEquals(1,files.size());String hash=FollowupSupport.hash(files.get(0));
        var binary=StudyPublicEvidence.map(policy.get("binary"));binary.put("maximum_work",1000000);policy.put("binary",binary);var second=analysis("second");var r2=new StudyCliExecutor().execute(second);assertEquals(State.COMPLETE,r2.state(),r2.summary());assertEquals(1,StudyPublicEvidence.list(r2.details().get("fits_reused")).size());assertEquals(hash,FollowupSupport.hash(files.get(0)));var t2=DelimitedData.readResult(second.outputDirectory().resolve("rare-primary-results.tsv"));assertEquals(10,t2.rows().size());for(String[] row:t2.rows())assertFalse(row[t2.column("adjusted_p")].equals("NA"));assertTrue(String.valueOf(r2.details().get("fits_reused")).contains("waiting_for_input"));
    }
    @Test void declaredUnknownSlopesAndUnverifiedRelatednessWaitForARealModelContract()throws Exception{
        setup(false,1000000);var hypothesis=StudyPublicEvidence.map(StudyPublicEvidence.list(study.get("hypotheses")).get(0));hypothesis.put("covariates",List.of("stratum","age"));study.put("hypotheses",List.of(hypothesis));var c=context("unknown","rare_variant_scores",scores.dependencyDirectories());var r=new StudyCliExecutor().execute(c);assertEquals(State.WAITING_FOR_INPUT,r.state());assertTrue(r.summary().contains("age"));assertFalse(Files.exists(c.outputDirectory().resolve("conditional-genotypes.tsv")));
        hypothesis.put("covariates",List.of("stratum"));var dataset=StudyPublicEvidence.map(StudyPublicEvidence.list(study.get("datasets")).get(0));dataset.put("metadata",Map.of("related_participants",true));study.put("datasets",List.of(dataset));var related=new StudyCliExecutor().execute(context("related","rare_variant_scores",scores.dependencyDirectories()));assertEquals(State.WAITING_FOR_INPUT,related.state());assertTrue(related.summary().contains("kinship"));
    }
    @Test void damagedDerivedFitIsRetainedAndRecomputedFromVerifiedRawInputs()throws Exception{
        setup(false,1000000);var first=analysis("damaged");var r1=new StudyCliExecutor().execute(first);assertEquals(State.COMPLETE,r1.state());seal(first,r1);Path cache;try(var paths=Files.list(first.outputDirectory().resolve("binary-fit-cache"))){cache=paths.findFirst().orElseThrow();}Files.writeString(cache,"invalid derived cache\n");String damaged=FollowupSupport.hash(cache);
        var second=analysis("recomputed");var r2=new StudyCliExecutor().execute(second);assertEquals(State.COMPLETE,r2.state(),r2.summary());assertEquals(0,StudyPublicEvidence.list(r2.details().get("fits_reused")).size());assertEquals(1,StudyPublicEvidence.list(r2.details().get("invalidated_fit_caches")).size());assertEquals(damaged,FollowupSupport.hash(cache));assertTrue(String.valueOf(r2.details().get("invalidated_fit_caches")).contains("recompute_from_verified_inputs"));
    }
    @Test void aHashSealedButStructurallyIncompleteDerivedFitIsNotReused()throws Exception{
        setup(false,1000000);var first=analysis("malformed");var fitted=new StudyCliExecutor().execute(first);seal(first,fitted);Path cache;try(var paths=Files.list(first.outputDirectory().resolve("binary-fit-cache"))){cache=paths.findFirst().orElseThrow();}var doc=StudyYaml.loadArtifact(cache);var result=StudyPublicEvidence.map(doc.get("result"));result.put("tests",List.of());doc.put("result",result);StudyPublicEvidence.write(cache,doc);String malformed=FollowupSupport.hash(cache);var manifest=StudyYaml.loadArtifact(first.outputDirectory().resolve("manifest.yaml"));var hashes=StudyPublicEvidence.map(manifest.get("output_sha256"));hashes.put(first.outputDirectory().relativize(cache).toString().replace('\\','/'),malformed);manifest.put("output_sha256",hashes);StudyPublicEvidence.write(first.outputDirectory().resolve("manifest.yaml"),manifest);
        var second=analysis("structural-recompute");var completed=new StudyCliExecutor().execute(second);assertEquals(State.COMPLETE,completed.state(),completed.summary());assertEquals(0,StudyPublicEvidence.list(completed.details().get("fits_reused")).size());assertEquals(1,StudyPublicEvidence.list(completed.details().get("invalidated_fit_caches")).size());assertEquals(malformed,FollowupSupport.hash(cache));
    }
    @Test void reusedPrivateInputsMustMatchTheRequestedScientificNull()throws Exception{
        setup(false,1000000);var binary=StudyPublicEvidence.map(policy.get("binary"));binary.put("strata_column","different_stratum");policy.put("binary",binary);var r=new StudyCliExecutor().execute(analysis("wrong-null"));assertEquals(State.WAITING_FOR_INPUT,r.state());assertTrue(r.summary().contains("different fixed null"));
    }
    @Test void changedCaseCodingAndGenotypeQcCannotReuseAnOldPrivateExport()throws Exception{
        setup(false,1000000);policy.put("minimum_mac",20);var qc=new StudyCliExecutor().execute(analysis("changed-qc"));assertEquals(State.WAITING_FOR_INPUT,qc.state());assertTrue(qc.summary().contains("different phenotype coding"));policy.remove("minimum_mac");
        var hypothesis=StudyPublicEvidence.map(StudyPublicEvidence.list(study.get("hypotheses")).get(0));var configAnalysis=StudyPublicEvidence.map(hypothesis.get("analysis"));configAnalysis.put("association",Map.of("model","glm","family","binomial","link","logit","case_value",0,"control_value",1));hypothesis.put("analysis",configAnalysis);study.put("hypotheses",List.of(hypothesis));var coding=new StudyCliExecutor().execute(analysis("changed-coding"));assertEquals(State.WAITING_FOR_INPUT,coding.state());assertTrue(coding.summary().contains("different phenotype coding"));
    }
    @Test void observedMonomorphicRowsRemainAvailableForOtherCohortsJointSets()throws Exception{
        setup(false,1000000);Path source=root.resolve("genotypes.vcf");var lines=Files.readAllLines(source);for(int i=0;i<lines.size();i++)if(lines.get(i).startsWith("1\t100\t")){String[] fields=lines.get(i).split("\t",-1);for(int j=9;j<fields.length;j++)fields[j]="0/0";lines.set(i,String.join("\t",fields));}Files.write(source,lines);var c=context("mono-scores","rare_variant_scores",scores.dependencyDirectories());var result=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,result.state(),result.summary());var t=DelimitedData.readResult(c.outputDirectory().resolve("variant-qc.tsv"));String[] row=t.rows().stream().filter(r->r[t.column("variant_id")].equals("1:100:A:G")).findFirst().orElseThrow();assertEquals("true",row[t.column("retained")]);assertEquals(0,Double.parseDouble(row[t.column("minor_allele_count")]));assertTrue(Files.readString(c.outputDirectory().resolve("conditional-genotypes.tsv")).contains("1:100:A:G\t0.0"));
    }
    @Test void aCompletePrimaryFamilyRemainsAggregateEvidenceWhenOtherScopesWait()throws Exception{
        setup(false,1000000);var c=analysis("complete-primary");var fitted=new StudyCliExecutor().execute(c);assertEquals(State.COMPLETE,fitted.state());var details=new LinkedHashMap<String,Object>(fitted.details());details.put("incomplete_scopes",List.of("leave-one-out:unresolved"));seal(c,new Result(State.WAITING_FOR_INPUT,"Synthetic unresolved sensitivity scope; complete primary retained",fitted.outputs(),details));
        var inventory=context("inventory","finding_inventory",Map.of("rare",c.outputDirectory()));assertEquals(State.COMPLETE,new StudyFindingInventory().execute(inventory).state());String dossier=Files.readString(inventory.outputDirectory().resolve("finding-inventory.jsonl"));assertFalse(dossier.contains("private_s"));assertTrue(dossier.contains("complete_primary_family_other_requested_scopes_unresolved"),dossier);assertTrue(dossier.contains("finite_conditional_genotype_pattern_enumeration"),dossier);assertTrue(dossier.contains("n_cases"),dossier);assertTrue(dossier.contains("constant_evaluated_null"),dossier);
    }
}
